export function wordSearchIi(board            , words          )           {
const h=board.length,w=h?board[0].length:0;function exists(word       )        {const used=new Set        ();function dfs(r       ,c       ,i       )        {if(i===word.length)return true;if(r<0||r>=h||c<0||c>=w||used.has(r*w+c)||board[r][c]!==word[i])return false;used.add(r*w+c);const ok=dfs(r+1,c,i+1)||dfs(r-1,c,i+1)||dfs(r,c+1,i+1)||dfs(r,c-1,i+1);used.delete(r*w+c);return ok;}for(let r=0;r<h;r++)for(let c=0;c<w;c++)if(dfs(r,c,0))return true;return false;}return [...new Set(words)].filter(exists).sort();
}

